// P6: Summe aller Zahlen von a bis b
public static int summeVonBis(int a, int b) {
    int s = 0;
    for (int i = a; i < b; i++) {
        s = s + i;
    }
    return s;
}

// ranke(0) = 1, jeden Tag 3 Blätter mehr
public static int ranke(int tage) {
    return ranke(tage - 1) + 3;
}
// richtig:
public static int ranke(int tage) {
    if (tage == 0) {
        return 1;
    }
    return ranke(tage - 1) + 3;
}

