public static int zaehleAnfang(String[] r, String z) {
    int anzahl = 0;
    for (int i = 1; i < r.length; i++) {
        if (r[i].substring(0, 1) == z) {
            anzahl++;
        }
    }
    return anzahl;
}

public static int zaehleAnfang(String[] r, String z) {
    int anzahl = 0;
    for (int i = 0; i < r.length; i++) {
        if (r[i].length() > 0
                && r[i].substring(0, 1).equals(z)) {
            anzahl++;
        }
    }
    return anzahl;
}
